arguments.new_str:
using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine();

// Setup
var smallText = "The quick brown fox jumps over the lazy dog near the river bank";
var rng = new Random(42);
var words = new string[1000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(2, 12);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(0, 26));
    words[i] = new string(chars);
}
var largeText = string.Join(' ', words);

var small = new TextAnalyzer(smallText);
var large = new TextAnalyzer(largeText);

const int warmup = 1000;
const int iterations = 100_000;

// Benchmark helper
void Bench(string name, Action action)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    // Collect multiple samples
    var times = new double[5];
    for (int s = 0; s < times.Length; s++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++) action();
        sw.Stop();
        times[s] = sw.Elapsed.TotalNanoseconds / iterations;
    }

    Array.Sort(times);
    // Use median
    var median = times[times.Length / 2];
    Console.WriteLine($"  {name,-35} {median,10:F2} ns/op (median of {times.Length} runs)");
}

Console.WriteLine("Small input (12 words):");
Bench("AverageWordLength", () => { var r = small.AverageWordLength(); Consume(r); });
Bench("WordLengthHistogram", () => { var r = small.WordLengthHistogram(); Consume(r); });
Bench("UniqueWordCount", () => { var r = small.UniqueWordCount(); Consume(r); });

Console.WriteLine();
Console.WriteLine("Large input (1000 words):");
Bench("AverageWordLength", () => { var r = large.AverageWordLength(); Consume(r); });
Bench("WordLengthHistogram", () => { var r = large.WordLengthHistogram(); Consume(r); });
Bench("UniqueWordCount", () => { var r = large.UniqueWordCount(); Consume(r); });

[MethodImpl(MethodImplOptions.NoInlining)]
static void Consume<T>(T value) { }

